"""Student-safe export plumbing; no PDF artifacts are generated by these tests."""

import json
import subprocess
import sys

import pytest

from course_tutor.api import LumenCore
from course_tutor.errors import ValidationError
from course_tutor.assessment.export import export_paper, formatted_text, render_paper_html, print_pdf


@pytest.fixture
def saved(tmp_path):
    with LumenCore(tmp_path/'workspace') as core:
        core.create_course('Example', course_id='one')
        versions = []
        for text in ('שאלה ראשונה: חשבו \\(a_{i}+1\\).', 'Question two: $\\frac{1}{2}$'):
            vid = core.create_exercise('one', text, text,
                subparts=[{'key':'a', 'private_answer':'PRIVATE_SUBPART_ANSWER'}],
                reference_solution='PRIVATE_REFERENCE', rubric={'correct_option':'PRIVATE_KEY'})['exercise_version_id']
            core.validate_exercise_version(vid, expected_revision=1, checks={'review':True})
            versions.append(vid)
        assessment = core.create_assessment('one', 'Test', {}, list(reversed(versions)), learner_id='student')
        aid = assessment['data']['assessment_id']
        yield core, aid, versions


def test_paper_preserves_saved_order_and_excludes_teacher_fields(saved):
    core, aid, versions = saved
    before = core.con.total_changes
    paper = core.assessment_paper(aid, 'one')
    assert [q['exercise_version_id'] for q in paper['questions']] == list(reversed(versions))
    assert 'PRIVATE' not in json.dumps(paper)
    assert core.con.total_changes == before
    assert core.con.execute('SELECT COUNT(*) FROM attempts').fetchone()[0] == 0
    with pytest.raises(ValidationError):
        core.assessment_paper(aid, 'other')
    core.update_exercise_version(versions[0], question_text='Needs re-review', expected_revision=1)
    with pytest.raises(ValidationError, match='unvalidated'):
        core.assessment_paper(aid)


def test_offline_math_and_source_markup_are_rendered_safely(saved):
    core, aid, _ = saved
    paper = core.assessment_paper(aid)
    html = render_paper_html(paper)
    assert '<math' in html and '<mfrac>' in html
    assert 'PRIVATE' not in html
    assert '<script' not in html and 'https://' not in html
    assert '\\frac' not in html
    assert '&lt;img' in formatted_text('<img src="https://example.com">')
    assert '<msub>' in formatted_text('(a)_{i}')


def test_renderer_failure_does_not_publish_a_pdf_or_success_manifest(saved, tmp_path, monkeypatch):
    import importlib
    module = importlib.import_module('course_tutor.assessment.export')
    core, aid, _ = saved
    paper = core.assessment_paper(aid)
    monkeypatch.setattr(module, 'browser_executable', lambda: None)
    destination = tmp_path/'output'
    with pytest.raises(ValidationError, match='requires Chrome'):
        export_paper(paper, destination)
    assert not destination.exists()
    monkeypatch.setattr(module, 'browser_executable', lambda: '/native/chrome')
    def fail(*args):
        raise ValidationError('Rendering failed')
    monkeypatch.setattr(module, 'print_pdf', fail)
    with pytest.raises(ValidationError, match='Rendering failed'):
        export_paper(paper, destination)
    assert not list(destination.rglob('*.pdf'))
    assert not (destination/'presentation.json').exists()


def test_chrome_exit_without_pdf_is_not_success(tmp_path, monkeypatch):
    import importlib
    module = importlib.import_module('course_tutor.assessment.export')
    seen = []
    def no_output(command, **kw):
        seen.append(command)
        return subprocess.CompletedProcess(command, 0)
    monkeypatch.setattr(module.subprocess, 'run', no_output)
    html, pdf = tmp_path/'test.html', tmp_path/'test.pdf'
    html.write_text('<p>test</p>')
    with pytest.raises(ValidationError, match='rendering failed'):
        print_pdf(html, pdf, '/native/chrome')
    assert '--headless' in seen[0]
    assert any(arg.startswith('--print-to-pdf=') for arg in seen[0])
    assert not pdf.exists()


def test_paper_cli_is_student_safe(saved):
    core, aid, versions = saved
    proc = subprocess.run([sys.executable,'-m','course_tutor.cli','assessment-paper','-w',str(core.workspace_root),
                           '-c','one','-j',json.dumps({'assessment_id':aid})],capture_output=True,text=True)
    assert proc.returncode == 0
    assert len(json.loads(proc.stdout)['data']['questions']) == 2
    assert 'PRIVATE' not in proc.stdout


def test_create_receipt_signals_pdf_step_and_replays_without_new_reservations(saved):
    core, _, versions = saved
    first = core.create_assessment('one','New paper',{},versions,request_id='paper-request')
    second = core.create_assessment('one','New paper',{},versions,request_id='paper-request')
    assert first['data']['delivery']['default_format'] == 'pdf'
    assert first['data']['delivery']['status'] == 'not_exported'
    assert first['data']['delivery']['next_operation'] == 'export-assessment'
    assert second['data'] == first['data'] and second['idempotent_replay']
    assert not list(core.workspace_root.rglob('*.pdf'))


def test_default_export_is_inside_workspace_course_tests(saved, monkeypatch):
    import importlib
    module = importlib.import_module('course_tutor.assessment.export')
    core, aid, _ = saved
    monkeypatch.setattr(module, 'export_paper', lambda paper, directory: {'directory': str(directory)})
    result = core.export_assessment(aid)
    assert result['directory'] == str(core.workspace_root/'courses/one/tests'/aid)
    brief = core.course_brief('one', learner_id='student')
    assert brief['course_directory'] == str(core.workspace_root/'courses/one')
    assert brief['open_assessments'][0]['assessment_id'] == aid
    assert brief['open_assessments'][0]['pdf_exists'] is False
    assert core.course_brief('one', learner_id='someone-else')['open_assessments'] == []


def test_imported_course_directory_is_used_and_mismatches_rejected(tmp_path, monkeypatch):
    import importlib
    module = importlib.import_module('course_tutor.assessment.export')
    course = tmp_path/'course with spaces'
    course.mkdir()
    (course/'course.json').write_text('{"course_id":"one"}')
    source = course/'exam.txt'
    source.write_text('Question 1: Compute the requested value.')
    with LumenCore(tmp_path/'workspace') as core:
        core.create_course('Imported course', course_id='one')
        sid = core.ingest_source('one', source, role='exam')['data']['source_version_id']
        q = core.list_questions('one', sid)['questions'][0]
        core.annotate_question('one', q['id'], 1, {'import_origin':str(course)})
        core.review_question_occurrence('one', q['id'], 2, 'accepted', 'Compared with source text')
        core.validate_exercise_version(q['exercise_version_id'], expected_revision=1, checks={'review':True},
            reference_solution='Checked fixture reference', rubric={'max_points':1})
        aid = core.create_assessment('one','Test',{},[q['exercise_version_id']])['data']['assessment_id']
        monkeypatch.setattr(module, 'export_paper', lambda paper, directory: {'directory':str(directory)})
        assert core.export_assessment(aid)['directory'] == str(course/'tests'/aid)
        assert core.list_courses()['courses'][0]['directory'] == str(course)
        (course/'course.json').write_text('{"course_id":"other"}')
        with pytest.raises(ValidationError, match='different course'):
            core.export_assessment(aid)
        explicit = tmp_path/'chosen-export'
        assert core.export_assessment(aid, output_directory=explicit)['directory'] == str(explicit)


def test_browser_discovery_uses_known_playwright_cache(tmp_path, monkeypatch):
    from pathlib import Path
    import importlib
    module = importlib.import_module('course_tutor.assessment.export')
    monkeypatch.setattr(module.shutil, 'which', lambda name: None)
    monkeypatch.setattr(Path, 'home', classmethod(lambda cls: tmp_path))
    monkeypatch.delenv('LUMEN_BROWSER_EXECUTABLE', raising=False)
    cache = tmp_path/'browsers'
    monkeypatch.setenv('PLAYWRIGHT_BROWSERS_PATH', str(cache))
    for revision in (999,1243):
        browser = cache/f'chromium-{revision}'/'chrome-linux64/chrome'
        browser.parent.mkdir(parents=True)
        browser.write_text('test-only executable path')
        browser.chmod(0o700)
    assert module.browser_executable() == str(cache/'chromium-1243/chrome-linux64/chrome')
    explicit = tmp_path/'preferred-chrome'
    explicit.write_text('test-only executable path')
    explicit.chmod(0o700)
    monkeypatch.setenv('LUMEN_BROWSER_EXECUTABLE',str(explicit))
    assert module.browser_executable() == str(explicit)


@pytest.mark.parametrize('kind', ['empty', 'invalid', 'zero_pages'])
def test_staged_renderer_rejects_unreadable_and_cleans_partial(saved, tmp_path, monkeypatch, kind):
    import importlib
    from pypdf import PdfWriter
    module = importlib.import_module('course_tutor.assessment.export')
    core, aid, _ = saved
    stage = tmp_path/'owned-stage'
    stage.mkdir()
    (stage/'owner.json').write_text('owned')
    monkeypatch.setattr(module, 'browser_executable', lambda: '/native/chrome')
    def render(html, pdf, executable):
        if kind == 'zero_pages':
            PdfWriter().write(pdf)
        else:
            pdf.write_bytes(b'' if kind == 'empty' else b'not PDF')
    monkeypatch.setattr(module, 'print_pdf', render)
    with pytest.raises(ValidationError, match='readable PDF'):
        module.render_staged_paper(core.assessment_paper(aid), stage)
    assert sorted(p.name for p in stage.iterdir()) == ['owner.json']


def test_staged_real_pdf_privacy_and_hashes(saved, tmp_path):
    import hashlib
    from pypdf import PdfReader
    from course_tutor.assessment.export import browser_executable, render_staged_paper
    if not browser_executable():
        pytest.skip('No supported browser available for real PDF smoke test')
    core, aid, _ = saved
    paper = core.assessment_paper(aid)
    stage = tmp_path/'owned-stage'
    stage.mkdir()
    changes = core.con.total_changes
    result = render_staged_paper(paper, stage)
    assert result['presentation_status'] == 'rendered_pending_visual_review'
    assert result['page_count'] > 0
    manifest = json.loads((stage/'presentation.json').read_text())
    for name, digest in manifest['artifacts'].items():
        assert hashlib.sha256((stage/name).read_bytes()).hexdigest() == digest
    text = '\n'.join(p.extract_text() for p in PdfReader(stage/'test.pdf').pages)
    assert 'PRIVATE' not in text
    assert 'PRIVATE' not in (stage/'test.html').read_text()
    assert 'PRIVATE' not in json.dumps(manifest)
    assert core.con.total_changes == changes
    with pytest.raises(ValidationError, match='without paper artifacts'):
        render_staged_paper(paper, stage)


def test_csv_data_is_a_safe_complete_table():
    from course_tutor.assessment.export import render_question_text
    html = render_question_text('Setup\nday,crates\nMonday,18\nTuesday,5\n\nFind the total.')
    assert '<table>' in html and '<th>day</th>' in html
    assert '<td>Monday</td><td>18</td>' in html
    assert '<td>Tuesday</td><td>5</td>' in html
    assert 'Find the total.' in html
